---

### 📄 JSON Schema: Trade Approval Workflow

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Trade Approval Workflow",
  "description": "A standard structure for representing a trade approval workflow in a system.",
  "type": "object",
  "properties": {
    "workflowId": {
      "type": "string",
      "description": "Unique identifier for the workflow."
    },
    "tradeId": {
      "type": "string",
      "description": "Unique identifier for the trade being approved."
    },
    "tradeType": {
      "type": "string",
      "description": "Type of trade (e.g., purchase, sale, service)."
    },
    "status": {
      "type": "string",
      "description": "Current status of the workflow (e.g., pending, approved, rejected, in_review)."
    },
    "createdBy": {
      "type": "string",
      "description": "User or system that initiated the trade."
    },
    "createdAt": {
      "type": "string",
      "format": "date-time",
      "description": "Timestamp when the trade was created."
    },
    "approvals": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "approverId": {
            "type": "string",
            "description": "Unique identifier of the approver."
          },
          "approverRole": {
            "type": "string",
            "description": "Role of the approver (e.g., manager, finance, admin)."
          },
          "approvalStatus": {
            "type": "string",
            "description": "Status of the approval (e.g., pending, approved, rejected)."
          },
          "approvedAt": {
            "type": "string",
            "format": "date-time",
            "description": "Timestamp when the approval was made."
          },
          "comments": {
            "type": "string",
            "description": "Optional comments from the approver."
          }
